let libraryItems=[],accountEpoch=0,libraryGeneration=0,favoriteRevision=0;const favoriteJobs=new Map();
import {discoveryOrder,startHero} from './discovery.js?v=discovery-1';
import {extractCover,mobileDevice,mobileLayout,portraitWork,mobileUse} from './media-tools.js?v=media-4';
let discoveryRanking=[],stopHero=()=>{};
matchMedia('(max-width:700px)').addEventListener('change',()=>{if(route==='downloads'){paintLibrary();return;}if(route!=='discover'||!document.querySelector('#grid'))return;renderGrid();stopHero();stopHero=startHero(document.querySelector('.hero-art'),works.filter(w=>mobileLayout()?portraitWork(w):!portraitWork(w)),discoveryRanking,{image,escape});});
const creators={ccbcm:{name:'CCBCM',letter:'C',note:'我的壁纸与创作，也整理一些注明来源的开源壁纸。',kind:'站内创作者'}};
const works=[
{id:"blue",name:"蓝色呼吸",author:"ccbcm",type:"动态壁纸",tag:"极简",cover:"blue.jpg",video:"/gallery/media/blue.mp4",text:"柔和的蓝色渐变，缓缓流动。下载后可在 CCBCM 插件中使用。",original:"CCBCM",source:"https://github.com/ccbcm/The-world",license:"CCBCM 原创演示"},
{id:'cat',name:'一只小猫',author:'ccbcm',sourceAuthor:'Daylin Morgan',type:'静态壁纸',tag:'极简',cover:'cat.svg',text:'一点柔和的颜色，和一只不打扰你的小猫。保留原作者的 SVG 壁纸，可直接下载。',original:'Cat',source:'https://github.com/daylinmorgan/catppuccin-wallpapers',license:'MIT'},
{id:'lines',name:'线条的秩序',author:'ccbcm',sourceAuthor:'Daylin Morgan',type:'静态壁纸',tag:'极简',cover:'lines.svg',text:'干净的线条，让桌面留一点空。来自 Catppuccin Wallpapers 的原始矢量作品。',original:'Lines',source:'https://github.com/daylinmorgan/catppuccin-wallpapers',license:'MIT'},
{id:'caffeine',name:'咖啡时间',author:'ccbcm',sourceAuthor:'Daylin Morgan',type:'静态壁纸',tag:'极简',cover:'caffeine.svg',text:'给工作间隙留一杯咖啡。简洁的分子图案，适合喜欢安静桌面的你。',original:'Caffeine',source:'https://github.com/daylinmorgan/catppuccin-wallpapers',license:'MIT'},
{id:'tux',name:'企鹅朋友',author:'ccbcm',sourceAuthor:'Daylin Morgan',type:'静态壁纸',tag:'极简',cover:'tux.svg',text:'熟悉的小企鹅，换上柔和的底色。来自原作者的开源壁纸系列。',original:'Tux',source:'https://github.com/daylinmorgan/catppuccin-wallpapers',license:'MIT'}];
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');let saved=new Set();let filter='全部',query='',route='discover',toastTimer;
const image=w=>w.poster||'/gallery/media/'+w.cover;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){let el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function heart(w){return `<button class="heart ${saved.has(w.id)?'selected':''}" ${favoriteJobs.has(w.id)?'disabled aria-busy="true"':''} data-save="${w.id}" aria-label="${saved.has(w.id)?'取消收藏':'收藏'} ${escape(w.name)}" aria-pressed="${saved.has(w.id)}">${saved.has(w.id)?'♥':'♡'}</button>`}
function card(w){const author=w.ownerLogin||(creators[w.author]?.name||'作者')+(w.author==='ccbcm'?'':' · 开源精选'),href=w.uploaded?'#people/'+encodeURIComponent(w.ownerLogin):'#creator/'+w.author;return `<article class="card catalog-card"><button class="cover" data-work="${w.id}" aria-label="查看 ${escape(w.name)}"><img src="${image(w)}" alt="${escape(w.name)}" loading="lazy" width="600" height="375"><span class="badge">${escape(w.type)}</span></button><div class="card-info"><div class="card-text"><h3 title="${escape(w.name)}">${escape(w.name)}</h3><a class="author" title="${escape(author)}" href="${href}">${escape(author)}</a></div>${heart(w)}</div></article>`}
function toolbar(title,sub){return `<section class="intro-line"><div><h2>${title}</h2><div class="subtitle">${sub}</div></div><label class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="搜索作品" placeholder="搜壁纸、风格或作者" value="${escape(query)}" type="search"></label></section><div class="filters" role="group" aria-label="作品分类">${['全部','动态壁纸','静态壁纸','极简','自然'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><section class="grid" id="grid" aria-label="作品"></section>`}
function renderGrid(){let list=works.filter(w=>(route!=='discover'||(mobileLayout()?portraitWork(w):!portraitWork(w)))&&(route!=='wallpapers'||w.type!=='互动作品')&&(route!=='saved'||saved.has(w.id))&&(!route.startsWith('creator/')||w.author===route.split('/')[1])&&(filter==='全部'||w.type===filter||w.tag===filter)&&(`${w.name} ${w.ownerLogin||creators[w.author]?.name||''} ${w.tag} ${w.original}`).toLowerCase().includes(query.toLowerCase()));if(route==='discover')list=discoveryOrder(list,discoveryRanking);document.querySelector('#grid').innerHTML=list.length?list.map(card).join(''):`<div class="empty">${route==='saved'?'还没有收藏。遇到喜欢的作品，点一下 ♡ 就能留在这里。':'没有找到合适的作品，换个词试试。'}</div>`}
function render(){stopHero();stopHero=()=>{};route=location.hash.slice(1)||'discover';if(route==='wallpapers'){location.hash='discover';return;}filter='全部';query='';if(dialog.open)dialog.close();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route||route.startsWith('creator/')&&a.dataset.nav==='creators'));
document.querySelector('.account-menu').open=false;
if(route==='creator-review'){renderCreatorReview();return;}
if(route==='reports'){renderReports();return;}
if(route==='moderation'){renderModeration();return;}
if(route==='plugin'){app.innerHTML='<section class="intro-line"><div><h1>CCBCM 插件</h1><p class="subtitle">为电脑和手机准备的轻量工具，选好设备，直接使用。</p></div></section>'+'<div class="plugin-platforms">'+document.querySelector('#plugin-page').innerHTML+'</div>';return;}
if(['studio','me','settings'].includes(route)){renderPersonal(route);return;}
if(route==='saved'){history.replaceState(null,'','#downloads');route='downloads';}if(route.startsWith('people/')){renderPublic(route.slice(7));return;}if(!['discover','wallpapers','creators','downloads','saved'].includes(route)&&!route.startsWith('creator/')){app.innerHTML='<div class="empty"><h1>没有找到这个页面</h1><p>你可以回到发现，或从个人菜单进入自己的空间。</p><a class="pill" href="#discover">返回发现</a></div>';return;}
if(route==='downloads'){renderDownloads();return}
if(route==='creators'){renderCreators();return;}
if(route.startsWith('creator/')){renderPublic(route.slice(8));return;}
else{const isHome=route==='discover';app.innerHTML=(isHome?`<section class="hero"><div class="hero-copy"><p class="eyebrow">A LITTLE ESCAPE</p><h1>换个喜欢的风景。</h1><p>让桌面安静一点，也生动一点。<br>挑一张壁纸，看看创作者的世界。</p><a href="#discover" class="pill">去逛逛 <span>↗</span></a></div><div class="hero-art"><button class="hero-open" data-work="blue" aria-label="查看蓝色呼吸"><img src="/gallery/media/blue.jpg" alt="柔和的蓝色渐变" width="1400" height="850" fetchpriority="high"><div class="hero-label"><div><strong>蓝色呼吸</strong><small>CCBCM · 动态壁纸</small></div></div></button><div class="hero-controls" role="group" aria-label="背景轮播"><button type="button" data-hero-prev aria-label="上一张">‹</button><span class="hero-position">1 / 1</span><button type="button" data-hero-next aria-label="下一张">›</button></div></div></section>`:'')+toolbar(route==='saved'?'留住喜欢的':route==='wallpapers'?'挑一张，陪你工作':'值得停留的风景',route==='saved'?'收藏保存在这台设备的浏览器里。':'先看封面，喜欢再点开。')}
renderGrid();if(route==='discover')stopHero=startHero(document.querySelector('.hero-art'),works.filter(w=>mobileLayout()?portraitWork(w):!portraitWork(w)),discoveryRanking,{image,escape});document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;renderGrid()});}
function openWork(id){let w=works.find(w=>w.id===id);if(!w)return;recordClick(id);let dynamic=w.type==='动态壁纸';if(w.uploaded){openUploaded(w);return;}if(w.video){openVideo(w);return;}document.querySelector('#detail-body').innerHTML=`<div class="detail-cover"><img src="${image(w)}" alt="${w.name}">${dynamic?'<button class="pill start" id="start">▷ 播放预览</button>':''}</div><div class="detail-copy"><p class="eyebrow">${w.type} · ${w.tag}</p><h2>${w.name}</h2><a class="author" href="#creator/${w.author}">${creators[w.author].name} ↗</a><p>${w.text}</p><div class="detail-actions">${w.id==='city'?'<a class="pill" href="/city.html">进入城市 ↗</a>':`<button class="pill" data-download="${w.id}">下载</button>`}${heart(w)}</div><div class="meta"><span>${w.sourceAuthor?'CCBCM 整理 · 原作者 '+escape(w.sourceAuthor):w.original}</span><span>${w.license}</span><span>${dynamic?'网页动态效果':w.id==='city'?'制作中 · 电脑体验更好':'SVG · 可缩放'}</span></div>${dynamic?'<p class="subtitle">这是网页动态效果，不是视频文件。用作桌面壁纸时，需要支持网页壁纸的软件。关闭预览后会停止运行。</p>':''}</div>`;dialog.showModal();document.querySelector('#start')?.addEventListener('click',()=>{document.querySelector('.detail-cover').innerHTML=`<iframe src="/gallery/preview.html?id=${id}" title="${w.name} 动态预览" sandbox="allow-scripts allow-same-origin"></iframe>`});}
document.addEventListener('click',e=>{let work=e.target.closest('[data-work]');if(work)openWork(work.dataset.work);let b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderGrid()}let save=e.target.closest('[data-save]');if(save)toggleFavorite(save);});

dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.querySelector('#detail-body').replaceChildren());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});document.querySelector('#about').onclick=()=>{document.querySelector('#detail-body').innerHTML='<div class="detail-copy"><h2>让桌面有点不同。</h2><p>CCBCM 是一个分享壁纸与创作的地方。先看看预览，点亮爱心的壁纸会排在“我的下载”前面。下载后即可使用。</p><p>安装桌面插件后，在“我的下载”点击“使用”，插件会准备壁纸并应用到桌面。目前支持视频动态壁纸和站内静态壁纸。</p><p>GitHub 登录后即可收藏和使用壁纸。想分享自己的创作，可以申请成为创作者，由 CCBCM 审核；作品提交后也需审核再上架。</p><p>收藏和下载仅自己可见，公开主页展示已发布的作品。收录的开源壁纸会在详情中保留原作者与许可说明。</p></div>';dialog.showModal()};


let accountPromise;
async function api(path,options={}){
 if(['127.0.0.1','localhost'].includes(location.hostname))throw Error('这是本地页面预览，账号功能请到 ccbcm.net 使用。');
 const read=(options.method||'GET').toUpperCase()==='GET';
 for(let attempt=0;attempt<(read?2:1);attempt++){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
  try{
   const r=await fetch('/api/'+path,{credentials:'same-origin',...options,signal:controller.signal});
   if(read&&attempt===0&&[502,503,504].includes(r.status)){await r.body?.cancel();continue;}
   let data;try{data=await r.json()}catch{throw Error('服务没有正确响应，请重试。')}
   if(!r.ok)throw Object.assign(Error(data.error||'暂时无法完成，请重试。'),{status:r.status});return data;
  }catch(error){if(read&&attempt===0&&(error.name==='AbortError'||error instanceof TypeError))continue;
   if(error.name==='AbortError'||error instanceof TypeError)throw Error('连接暂时中断，请点重试，无需关闭页面。');throw error;
  }finally{clearTimeout(timer)}
 }
}
function account(){return accountPromise||(accountPromise=api('account').catch(error=>{accountPromise=null;throw error}));}
function loginPanel(ready){return `<div class="empty account-panel"><h2>${ready?'把喜欢的壁纸留在这里':'我的下载即将开放'}</h2><p>${ready?'登录后，下载和收藏会保存在你的账号中。':'账号服务正在配置。'}</p>${ready?'<button class="pill" type="button" data-open-login>使用邮箱登录</button><dialog class="login-sheet" data-login-sheet aria-label="选择登录方式"><div class="login-sheet-card"><button class="login-close" type="button" data-close-login aria-label="关闭登录">×</button><h3>选择登录方式</h3><p class="subtitle">邮箱验证码支持 Gmail、QQ 和其他常见邮箱。</p><a class="pill secondary" href="/api/auth/github">使用 GitHub 账号继续</a><form class="email-login" id="email-login-form"><label>邮箱<input name="email" type="email" autocomplete="email" placeholder="输入你的邮箱地址" required></label><div class="email-code-row"><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="验证码"><button class="pill secondary" type="button" data-email-code>获取验证码</button></div><button class="pill" type="submit">继续</button><p role="status"></p></form></div></dialog>':''}</div>`;}
async function saveDownload(id){const w=works.find(w=>w.id===id);if(!w)return false;try{const a=await account();if(!a.user){try{sessionStorage.setItem('ccbcm-pending-download',JSON.stringify({id,at:Date.now(),returnTo:route}));}catch{}document.querySelector('#detail-body').innerHTML=loginPanel(a.ready);if(!dialog.open)dialog.showModal();return false;}await api('downloads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});toast('已加入我的下载');if(route==='downloads')await renderDownloads();return true;}catch(e){toast(e.message);if(e.status===401)accountPromise=null;return false;}}
function paintLibrary(){const grid=document.querySelector('#download-grid');if(!grid)return;
 const merged=new Map(libraryItems.map(x=>[x.id,{...x,favorite:saved.has(x.id)}]));for(const id of saved)if(!merged.has(id))merged.set(id,{id,downloaded:false,favorite:true,date:0});
 const items=[...merged.values()].filter(x=>(x.downloaded||x.favorite)&&!['city','waves','clouds','net'].includes(x.id)).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||b.date-a.date||a.id.localeCompare(b.id));
 grid.innerHTML=items.map(x=>downloadCard(works.find(w=>w.id===x.id),x.id,!!x.downloaded)).join('')||'<div class="empty">还没有留下壁纸。点亮爱心，或下载一张喜欢的风景。<br><a class="pill secondary" href="#discover">去找壁纸</a></div>';
}
async function renderDownloads(){const generation=++libraryGeneration;app.innerHTML='<section class="intro-line"><div><h1>我的下载</h1><p class="subtitle">喜欢的排在前面。下载后，点使用就能换到桌面。</p></div><a class="pill secondary" href="#discover">去找壁纸 ↗</a></section><p class="subtitle">首次使用？<a href="#plugin">安装桌面插件</a></p><div id="library-import"></div><section class="grid" id="download-grid"><p>正在读取…</p></section>';
 try{const a=await account();if(route!=='downloads'||generation!==libraryGeneration)return;if(!a.user){document.querySelector('#download-grid').innerHTML=loginPanel(a.ready);return;}
 const revision=favoriteRevision,{items}=await api('library');if(route!=='downloads'||generation!==libraryGeneration)return;libraryItems=items;
 if(revision===favoriteRevision)saved=new Set(items.filter(x=>x.favorite).map(x=>x.id));for(const [id,desired] of favoriteJobs)desired?saved.add(id):saved.delete(id);paintHearts();paintLibrary();
 const old=legacyFavorites();if(old.length)document.querySelector('#library-import').innerHTML=`<details class="legacy-drafts"><summary>导入这台浏览器的旧收藏</summary><p>确认这 ${old.length} 件是你的收藏，再导入账号 @${escape(a.user.login)}。</p><button class="pill secondary" data-import-favorites>导入到这个账号</button><p id="import-status" role="status"></p></details>`;
 }catch(e){if(route==='downloads'&&generation===libraryGeneration)document.querySelector('#download-grid').innerHTML=`<div class="empty">${escape(e.message)}<br><button class="pill secondary" data-retry>重试</button></div>`;}}

function openVideo(w){if(w.uploaded){openUploaded(w);return;}document.querySelector('#detail-body').innerHTML=`<div class="detail-cover"><video controls muted loop playsinline preload="none" poster="${image(w)}" src="${w.video}" style="width:100%;height:100%;object-fit:cover"></video></div><div class="detail-copy"><p class="eyebrow">动态壁纸 · 极简</p><h2>${w.name}</h2><p>${w.text}</p><div class="detail-actions"><button class="pill" data-download="${w.id}">下载</button>${heart(w)}</div></div>`;dialog.showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-download]');if(b){e.preventDefault();b.disabled=true;const label=b.textContent;b.textContent='保存中…';let done=false;try{done=await saveDownload(b.dataset.download)}finally{b.disabled=done;b.textContent=done?'已下载':label;}}if(e.target.closest('[data-retry]')){accountPromise=null;renderDownloads();}if(e.target.closest('[data-logout]')){try{await api('logout',{method:'POST'});accountPromise=null;accountEpoch++;favoriteRevision++;libraryGeneration++;libraryItems=[];saved=new Set();await refreshAccount();location.hash='downloads';render();}catch(e){toast(e.message);}}});
async function refreshAccount(){try{const a=await account();const link=document.querySelector('#account-link');link.textContent=a.user?a.user.login:'我的空间';if(a.user){const {profile}=await api('profile');link.innerHTML=avatarHTML(profile)+`<span>${escape(profile.name)}</span>`;await loadFavorites();}document.querySelector('[data-review-link]').hidden=!a.reviewer;document.querySelector('.publish-link').textContent=a.creator?.status==='approved'?'发布作品':'成为创作者';document.querySelector('[data-creator-review-link]').hidden=!a.reviewer;link.setAttribute('aria-label','个人菜单');document.querySelector('.account-menu [data-logout]').hidden=!a.user;}catch{}}
refreshAccount();
if(new URLSearchParams(location.search).get('login')==='failed'){const reason=new URLSearchParams(location.search).get('reason');const messages={bad_verification_code:'授权已过期，请重新登录。',incorrect_client_credentials:'登录应用的密钥配置不匹配。',redirect_uri_mismatch:'登录回调地址不匹配。',token_exchange:'暂时无法连接 GitHub 登录服务。',token_exchange_failed:'GitHub 未能完成授权，请重新登录。',profile:'暂时无法读取 GitHub 公开身份。',database:'账号保存失败，请稍后重试。'};toast(messages[reason]||'登录未完成，请再试一次。');}

Promise.all([loadPublished(),loadDiscovery()]).finally(()=>{render();resumePendingDownload();});


function avatarHTML(p){return (p.customAvatar||p.avatar==='github')&&p.avatarUrl?`<img class="user-avatar" src="${escape(p.avatarUrl)}" alt="" referrerpolicy="no-referrer">`:`<span class="user-avatar avatar-${escape(p.avatar)}">${escape(p.name.slice(0,1))}</span>`;}
function localLink(){return ['127.0.0.1','localhost'].includes(location.hostname)?'<p><a class="pill" href="https://ccbcm.net/#settings">前往正式网站</a></p>':'';}
async function renderPersonal(page){
 const titles={studio:'创作中心',me:'个人主页',settings:'账号设置'};
 app.innerHTML=`<section class="intro-line"><h1>${titles[page]}</h1></section><div id="personal-body">正在读取…</div>`;
 try{const a=await account();if(route!==page)return;const body=document.querySelector('#personal-body');if(!a.user){body.innerHTML=loginPanel(a.ready);return;}
 if(page==='studio'){if(a.creator?.status!=='approved'){renderCreatorApplication(body,a.creator);return;}await renderDrafts(body);return;}
 const {profile:p}=await api('profile');if(route!==page)return;
 if(page==='me'){location.hash='people/'+p.login;return;}
 body.innerHTML=`<form id="profile-form" class="profile-form"><div class="profile-preview">${avatarPicker(p)}<div><h2>${escape(p.name)}</h2><p>GitHub · ${escape(p.login)}</p></div></div><label>昵称<input name="name" value="${escape(p.name)}" maxlength="40" required></label><label>简介<textarea name="bio" maxlength="300" rows="2" placeholder="介绍一下你自己，或喜欢的创作。">${escape(p.bio)}</textarea></label><input type="hidden" name="avatar" value="${escape(p.avatar)}"><p class="subtitle">昵称、头像和简介会展示在你的公开主页。下载和收藏仅自己可见。</p><div class="detail-actions"><button class="pill" type="submit">保存资料</button><a class="pill secondary" href="#people/${escape(p.login)}">查看公开主页</a></div><p id="profile-status" role="status"></p></form>`;growBio();
 }catch(e){if(route===page)document.querySelector('#personal-body').innerHTML=`<div class="empty">${escape(e.message)}${localLink()}<button class="pill secondary" data-personal-retry>重试</button></div>`;}
}
