let videoUploadBusy=false;
const videoState={reserved:'等待上传',uploading:'上传处理中',failed:'上传未完成',verifying:'正在校验文件',ready:'壁纸已保存 · 未发布',review:'已提交审核 · 尚未公开',approved:'审核通过 · 可以上架',published:'已公开发布',unlisted:'已下架 · 修改后可重新提交审核'};
async function renderDrafts(body){
 const data=await api('videos');if(route!=='studio')return;
 body.innerHTML=`<section class="upload-panel"><h2>上传壁纸</h2><p>一张图片，或一段动态风景。上传后填写介绍，再提交审核。</p><label class="pill video-pick">选择图片或视频<input type="file" accept="video/mp4,video/quicktime,video/webm,video/x-matroska,image/png,image/jpeg,.mp4,.mov,.webm,.mkv,.png,.jpg,.jpeg" data-new-video aria-label="选择图片或视频" ${videoUploadBusy?'disabled':''}></label><p class="upload-hint">支持 MP4、MOV、WebM、MKV、PNG、JPG · 单个文件最多 200 MB</p><progress id="video-progress" value="0" max="100" hidden></progress><p id="video-upload-status" role="status"></p></section><h2 class="draft-heading">我的壁纸</h2><section class="video-library">${data.items.map(v=>`<article class="video-work" data-video-card="${v.id}">${['ready','review','approved','published','unlisted'].includes(v.state)?wallpaperPreview(v,'/api/videos/'+v.id+'/content'):`<div class="empty">${videoState[v.state]||'处理中'}</div>`}<form data-video-form="${v.id}" method="post"><label>作品标题<input name="title" maxlength="100" required value="${escape(v.title)}" ${['review','approved','published'].includes(v.state)?'disabled':''}></label><label>作品简介<textarea name="description" maxlength="1500" rows="3" ${['review','approved','published'].includes(v.state)?'disabled':''}>${escape(v.description)}</textarea></label><p class="subtitle">${videoState[v.state]||v.state} · ${(v.size/1024/1024).toFixed(1)} MB</p><div class="detail-actions">${!['review','approved','published'].includes(v.state)?'<button class="pill secondary" type="submit">保存信息</button>':''}${['ready','unlisted'].includes(v.state)?`<label class="pill secondary video-pick">选择高清封面<input type="file" accept="image/jpeg,image/png" data-cover-work="${v.id}" aria-label="选择高清封面"></label><button class="pill" type="button" data-submit-video="${v.id}">提交发布审核</button>`:''}${['failed','reserved','uploading','verifying'].includes(v.state)?`<label class="pill secondary video-pick">重新选择原文件重试<input type="file" accept="video/mp4,video/quicktime,video/webm,video/x-matroska,image/png,image/jpeg,.mp4,.mov,.webm,.mkv,.png,.jpg,.jpeg" data-retry-video="${v.id}" aria-label="重新选择 ${escape(v.title)}"></label>`:''}${v.state==='approved'?`<button class="pill" type="button" data-publish-video="${v.id}">公开上架</button>`:''}${v.state==='published'?`<button class="pill secondary" type="button" data-unlist-video="${v.id}">下架作品</button>`:''}<button class="text-button" type="button" data-remove-video="${v.id}">移除作品</button></div><p class="video-feedback" role="status">${['ready','unlisted'].includes(v.state)&&v.review_reason?'审核说明：'+escape(v.review_reason):''}</p></form></article>`).join('')||'<div class="empty">还没有作品，先选一张图片或一段视频吧。</div>'}</section><details class="legacy-drafts"><summary>之前保存的文字草稿</summary><div id="legacy-drafts-body"></div></details>`;
 growBio();body.querySelector('.legacy-drafts').addEventListener('toggle',async e=>{if(e.target.open&&!body.querySelector('#legacy-drafts-body').textContent)try{await renderTextDrafts(body.querySelector('#legacy-drafts-body'));}catch(error){body.querySelector('#legacy-drafts-body').textContent=error.message;}});
}
function wallpaperPreview(v,url){const poster=(v.poster||'').replace(/^\/api\/published-videos\/([a-f0-9]+)\/cover/,url.replace(/\/content$/, '/cover'));return v.mime?.startsWith('image/')?`<img class="wallpaper-preview" loading="lazy" src="${url}" alt="${escape(v.title)}">`:`<video class="wallpaper-preview" controls loop playsinline preload="none" poster="${escape(poster)}" src="${url}" aria-label="${escape(v.title)}"></video>`;}
function uploadPart(id,n,uploadId,blob,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('PUT','/api/videos/'+id+'/part?n='+n);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-Upload-Id',uploadId);xhr.timeout=5*60000;xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(e.loaded);};xhr.onerror=()=>reject(Error('网络中断，请重新选择原文件重试。'));xhr.ontimeout=()=>reject(Error('上传超时，请稍后重试。'));xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText)}catch{reject(Error('服务器未正确响应，请重试。'));return;}if(xhr.status>=200&&xhr.status<300)resolve(data);else reject(Error(data.error||'上传失败，请重试。'));};xhr.send(blob);});}
async function uploadVideoBytes(id,file,onProgress){const state=await api('videos/'+id+'/begin',{method:'POST'});if(state.ready)return;for(let offset=0,n=1;offset<file.size;offset+=state.partSize,n++){const end=Math.min(file.size,offset+state.partSize);if(!state.parts[n])await uploadPart(id,n,state.uploadId,file.slice(offset,end),loaded=>onProgress(Math.floor((offset+loaded)/file.size*100)));onProgress(Math.floor(end/file.size*100));}
 // Completion is retryable: a timed-out request may have finished server-side.
 const waitForState=async()=>{for(let i=0;i<24;i++){const result=await api('videos');const item=result.items?.find(v=>v.id===id);if(item&&['ready','review','approved','published','unlisted'].includes(item.state))return {ok:true};if(item?.state==='failed')throw Error('文件校验未通过，请检查文件是否完整后重试。');await new Promise(r=>setTimeout(r,5000));}throw Error('云端校验仍在进行，请稍后回到创作中心查看结果。');};
 for(let attempt=0;attempt<3;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),180000);try{const response=await fetch('/api/videos/'+id+'/complete',{method:'POST',signal:controller.signal});let data;try{data=await response.json();}catch{data=null;}if(response.ok)return data;if(response.status===409&&data?.error?.includes('正在校验'))return await waitForState();throw Error(data?.error||'保存失败，请重试。');}catch(error){if(error.name==='AbortError'){try{return await waitForState();}catch(e){if(attempt===2)throw e;}}else if(attempt===2)throw error;await new Promise(r=>setTimeout(r,3000));}finally{clearTimeout(timer);}}
 return await waitForState();}
async function startVideoUpload(input){if(videoUploadBusy||!input.files.length)return;videoUploadBusy=true;input.disabled=true;const status=document.querySelector('#video-upload-status'),progress=document.querySelector('#video-progress');let id=input.dataset.retryVideo;
 try{const file=input.files[0],ext=file.name.split('.').pop().toLowerCase(),mime=({mp4:'video/mp4',mov:'video/quicktime',webm:'video/webm',mkv:'video/x-matroska',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg'})[ext];if(!mime||file.size>200*1024*1024||file.size<32)throw Error('请选择 200 MB 以内的 MP4、MOV、WebM、MKV、PNG 或 JPG。');status.textContent='正在提取高清封面…';let cover=null;try{cover=await extractCover(file);}catch(e){if(mime.startsWith('image/'))throw e;toast(e.message);}const poster='';
 const sha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');
 if(id){const {items}=await api('videos');const original=items.find(v=>v.id===id);if(!original||original.size!==file.size||original.sha256!==sha256)throw Error('请选择与上次相同的原文件。');}
 else{const record=await api('videos',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:file.name.replace(/\.[^.]+$/,'').slice(0,100),size:file.size,sha256,poster,mime})});id=record.id;}
 progress.hidden=false;progress.value=0;status.textContent='正在上传…';await uploadVideoBytes(id,file,percent=>{progress.value=percent;status.textContent=percent===100?'正在校验并保存壁纸…':`正在上传 ${percent}%`;});if(cover)await api('videos/'+id+'/cover',{method:'PUT',headers:{'Content-Type':'image/jpeg','X-Media-Width':String(cover.width),'X-Media-Height':String(cover.height)},body:cover.blob});status.textContent='壁纸已保存到云端。';toast(cover?'壁纸与高清封面已保存':'原视频已保存，请补充封面');if(route==='studio')await renderDrafts(document.querySelector('#personal-body'));
 }catch(error){status.textContent=error.message+(id?' 可重新选择原文件继续上传。':'');if(id)input.dataset.retryVideo=id;toast(error.message);}finally{videoUploadBusy=false;input.disabled=false;input.value='';const pick=document.querySelector('[data-new-video]');if(pick)pick.disabled=false;}
}
