async function renderModeration(){
 app.innerHTML='<section class="intro-line"><h1>作品审核</h1><a class="pill secondary" href="#reports">用户举报</a></section><div id="review-body">正在读取…</div>';
 try{const data=await api('moderation');if(route!=='moderation')return;
 document.querySelector('#review-body').innerHTML='<p class="subtitle">查看所有创作者提交的壁纸。通过后，作者即可公开上架。</p><section class="video-library">'+(data.items.map(v=>`<article class="video-work">${wallpaperPreview(v,'/api/moderation/'+v.id+'/content')}<div class="video-copy"><h2>${escape(v.title)}</h2><a href="#people/${escape(v.login)}">@${escape(v.login)}</a><p>${escape(v.description)}</p><p>${escape(videoState[v.state]||v.state)}</p>${['review','published'].includes(v.state)?`<form data-review-form="${v.id}"><label>审核说明<textarea name="reason" maxlength="500" rows="2" placeholder="退回时请告诉作者需要修改什么"></textarea></label><div class="detail-actions">${v.state==='published'?'<button class="pill secondary" type="submit" value="unlist">下架作品</button>':'<button class="pill" type="submit" value="approve">通过审核</button><button class="pill secondary" type="submit" value="reject">退回修改</button>'}</div><p role="status"></p></form>`:`<p>${escape(v.reason||'审核已完成')}</p>`}</div></article>`).join('')||'<div class="empty">暂时没有待审核的作品。</div>')+'</section>';
 }catch(e){if(route==='moderation')document.querySelector('#review-body').textContent=e.message;}
}
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-review-form]'))return;e.preventDefault();const form=e.target,decision=e.submitter?.value,reason=form.elements.reason.value.trim();if(decision!=='approve'&&!reason){form.querySelector('[role=status]').textContent='请填写退回或下架原因。';return;}form.querySelectorAll('button').forEach(x=>x.disabled=true);try{await api('moderation/'+form.dataset.reviewForm,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,reason})});toast(decision==='approve'?'已通过审核':decision==='unlist'?'作品已下架，作者可查看原因':'已退回，作者可查看原因');await renderModeration();}catch(error){form.querySelector('[role=status]').textContent=error.message;}finally{form.querySelectorAll('button').forEach(x=>x.disabled=false);}});

async function loadPublished(){try{const [{items},legacyCovers]=await Promise.all([api('published-videos'),fetch('/gallery/media/hd/index.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);document.querySelector('#connection-status')?.remove();for(let i=works.length-1;i>=0;i--)if(works[i].uploaded)works.splice(i,1);for(const v of items)works.push({id:v.id,name:v.title,text:v.description,poster:v.poster?.startsWith('/api/')?v.poster:(legacyCovers[v.id]?.poster||v.poster),width:v.width||legacyCovers[v.id]?.width,height:v.height||legacyCovers[v.id]?.height,cover:'blue.jpg',ownerLogin:v.login,author:'account:'+v.login,mime:v.mime||'video/mp4',type:v.mime?.startsWith('image/')?'静态壁纸':'动态壁纸',tag:v.mime?.startsWith('image/')?'图片':'视频',original:v.login,uploaded:true,content:'/api/published-videos/'+v.id+'/content',video:v.mime?.startsWith('image/')?null:'/api/published-videos/'+v.id+'/content'});}catch(e){toast('公开作品暂时无法读取，可在页面内重试。');document.querySelector('#connection-status')?.remove();const status=document.createElement('div');status.id='connection-status';status.className='empty';status.innerHTML='部分作品暂未加载 <button class="pill secondary" data-catalog-retry>重试</button>';app.before(status);}}
function openUploaded(w){document.querySelector('#detail-body').innerHTML=`<div class="detail-cover">${wallpaperPreview({mime:w.mime,title:w.name,poster:image(w)},w.content)}</div><div class="detail-copy"><h2>${escape(w.name)}</h2><a class="author" href="#people/${escape(w.ownerLogin)}">@${escape(w.ownerLogin)}</a><p>${escape(w.text)}</p><button class="pill" data-download="${w.id}">下载</button>${heart(w)}${w.uploaded?`<form data-report-work="${w.id}" class="report-form"><details><summary>举报作品</summary><label>举报原因<textarea name="reason" maxlength="500" required></textarea></label><button class="pill secondary" type="submit">提交举报</button><p role="status"></p></details></form>`:''}</div>`;dialog.showModal();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-publish-video],[data-unlist-video]');if(!b)return;b.disabled=true;try{const id=b.dataset.publishVideo||b.dataset.unlistVideo;await api('videos/'+id+(b.dataset.publishVideo?'/publish':'/unlist'),{method:'POST'});await loadPublished();if(route==='studio')await renderDrafts(document.querySelector('#personal-body'));toast(b.dataset.publishVideo?'作品已公开上架':'作品已下架');}catch(error){toast(error.message);}finally{b.disabled=false;}});

async function renderReports(){app.innerHTML='<h1>用户举报</h1><div id="reports-body">正在读取…</div>';try{const {items}=await api('moderation/reports');if(route!=='reports')return;document.querySelector('#reports-body').innerHTML=items.map(r=>`<article class="draft-card"><h2>${escape(r.title||'已移除作品')}</h2><p>举报人：${escape(r.login)}</p><p>${escape(r.reason)}</p><p>${r.state==='open'?'待处理':'已处理'}</p><a href="#moderation">前往作品审核</a>${r.state==='open'?`<button class="pill secondary" data-close-report="${r.id}">标记已处理</button>`:''}</article>`).join('')||'<p>暂时没有举报。</p>';}catch(e){if(route==='reports')document.querySelector('#reports-body').textContent=e.message;}}
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-report-work]'))return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:f.dataset.reportWork,reason:f.elements.reason.value})});f.querySelector('[role=status]').textContent='已收到举报，管理员会查看。';}catch(error){f.querySelector('[role=status]').textContent=error.message;}finally{b.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-close-report]');if(!b)return;b.disabled=true;try{await api('moderation/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.closeReport})});await renderReports();}catch(error){toast(error.message);b.disabled=false;}});

document.addEventListener('click',e=>{const a=e.target.closest('[data-apply-wallpaper]');if(!a)return;if(mobileDevice()){e.preventDefault();const id=a.getAttribute('href').split('/').pop(),w=works.find(w=>w.id===id);if(w)mobileUse(w,dialog,escape);return;}const card=a.closest('article');let hint=card.querySelector('.apply-feedback');if(!hint){hint=document.createElement('p');hint.className='apply-feedback subtitle';hint.setAttribute('role','status');card.querySelector('.download-info, .video-copy').appendChild(hint);}hint.replaceChildren(document.createTextNode('请允许浏览器打开 CCBCM 插件，壁纸会自动应用。没有反应？'));const link=document.createElement('a');link.href='#plugin';link.textContent='安装或更新插件';hint.appendChild(link);});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-remove-download]');if(!b)return;b.disabled=true;try{await api('downloads',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:b.dataset.removeDownload})});if(route==='downloads')await renderDownloads();toast(saved.has(b.dataset.removeDownload)?'下载已移除，收藏仍保留':'已移除下载');}catch(error){toast(error.message);b.disabled=false;}});

function downloadCard(w,id,downloaded=true){const usable=w&&(w.video||w.type==='静态壁纸'),compatible=w&&(mobileLayout()?portraitWork(w):!portraitWork(w)),author=w?(w.ownerLogin||creators[w.author]?.name||'作者'):'作品不可用',type=w?(w.video?'视频动态壁纸':'静态壁纸'):'已下架或暂不可用';return `<article class="card download-card">${w?`<button class="cover" data-work="${w.id}" aria-label="查看 ${escape(w.name)}"><img loading="lazy" src="${image(w)}" alt="${escape(w.name)}"></button>`:'<div class="cover unavailable-cover">作品暂不可用</div>'}<div class="download-info"><div class="library-title"><h3 title="${escape(w?.name||'不可用作品')}">${escape(w?.name||'不可用作品')}</h3>${w?heart(w):`<button class="heart ${saved.has(id)?'selected':''}" data-save="${id}" aria-label="取消收藏" aria-pressed="${saved.has(id)}">${saved.has(id)?'♥':'♡'}</button>`}</div>${w?`<a class="author" title="${escape(author)}" href="#${w.ownerLogin?'people/'+escape(w.ownerLogin):'creator/'+w.author}">作者 · ${escape(author)}</a>`:`<span class="author">${author}</span>`}<p class="download-kind">${escape(type)}${downloaded?'':' · 未下载'}</p><div class="download-actions">${usable?(downloaded?(compatible?`<a class="pill" data-apply-wallpaper href="${mobileDevice()?'ccbcm-mobile':'ccbcm-wallpaper'}://apply/${id}">使用</a>`:''):`<button class="pill" data-download="${id}">下载</button>`):'<button class="pill" disabled>暂不可用</button>'}${downloaded?`<button class="text-button" data-remove-download="${id}">移除下载</button>`:'<span class="library-save-note">已收藏</span>'}</div></div></article>`;}


document.addEventListener('click',async e=>{const b=e.target.closest('[data-catalog-retry]');if(!b)return;b.disabled=true;try{await loadPublished();render();}finally{b.disabled=false;}});

function renderCreatorApplication(body,access={status:'none'}){const pending=access.status==='pending';body.innerHTML=`<section class="creator-application"><h2>${pending?'申请已提交':'成为创作者'}</h2><p>${pending?'CCBCM 会查看你的申请，审核通过后就能上传作品。':'先介绍一下你想分享的作品，通过审核后即可上传和发布。浏览、收藏和使用壁纸不受影响。'}</p>${access.reason?`<p class="application-reason">审核说明：${escape(access.reason)}</p>`:''}${pending?'':`<form id="creator-application-form"><label>创作介绍<textarea name="note" rows="4" maxlength="500" required placeholder="想分享什么类型的壁纸？也可以附上你的作品链接。"></textarea></label><button class="pill" type="submit">提交申请</button><p role="status"></p></form>`}<button class="text-button" data-access-refresh>刷新状态</button></section>`;}
async function renderCreatorReview(){app.innerHTML='<section class="intro-line"><h1>创作者申请</h1></section><section id="creator-applications" class="video-library">正在读取…</section>';try{const {items}=await api('creator-applications');if(route!=='creator-review')return;document.querySelector('#creator-applications').innerHTML=items.map(x=>`<article class="creator-application"><h2 title="${escape(x.login)}">${escape(x.login)}</h2><details class="application-note"><summary>查看创作介绍</summary><p>${escape(x.note)}</p></details><p class="subtitle">${({pending:'等待审核',approved:'已通过',rejected:'已退回'})[x.status]}</p>${x.status==='pending'?`<form data-creator-decision="${escape(x.user_id)}"><label>审核说明<textarea name="reason" rows="2" maxlength="500" placeholder="退回时填写原因"></textarea></label><div class="detail-actions"><button class="pill" type="submit" value="approved">通过申请</button><button class="pill secondary" type="submit" value="rejected">退回修改</button></div><p role="status"></p></form>`:`<p>${escape(x.reason)}</p>`}</article>`).join('')||'<div class="empty">暂时没有创作者申请。</div>';}catch(e){if(route==='creator-review')document.querySelector('#creator-applications').innerHTML=`<div class="empty">${escape(e.message)}<button class="pill secondary" data-access-review-retry>重试</button></div>`;}}
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='creator-application-form'&&!form.matches('[data-creator-decision]'))return;e.preventDefault();const button=e.submitter;button.disabled=true;try{if(form.id==='creator-application-form'){await api('creator-application',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:new FormData(form).get('note')})});accountPromise=null;await refreshAccount();renderPersonal('studio');}else{await api('creator-applications/'+encodeURIComponent(form.dataset.creatorDecision),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:button.value,reason:new FormData(form).get('reason')})});renderCreatorReview();}}catch(error){form.querySelector('[role="status"]').textContent=error.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-access-refresh]')){accountPromise=null;await refreshAccount();renderPersonal('studio');}if(e.target.closest('[data-access-review-retry]'))renderCreatorReview();});

document.addEventListener('input',e=>{if(e.target.matches('.creator-application textarea')){e.target.style.height='auto';e.target.style.height=e.target.scrollHeight+'px';}});

async function renderCreators(){app.innerHTML='<section class="intro-line"><div><h1>看看谁在创作</h1><p class="subtitle">从一件喜欢的作品，认识它背后的人。</p></div></section><section class="creators-grid" id="creator-directory">正在读取…</section>';try{const {items}=await api('creators');if(route!=='creators')return;document.querySelector('#creator-directory').innerHTML=items.length?items.map(p=>`<article class="creator-card live-creator">${avatarHTML(p)}<h2 title="${escape(p.name)}">${escape(p.name)}</h2><span class="subtitle">${p.publishedCount} 件公开作品</span><p title="${escape(p.bio)}">${escape(p.bio||'还没有填写简介。')}</p><a class="pill secondary" href="#people/${encodeURIComponent(p.login)}">看看作品 ↗</a></article>`).join(''):'<div class="empty">创作者们正在准备作品。</div>';}catch(error){if(route==='creators')document.querySelector('#creator-directory').innerHTML=`<div class="empty">${escape(error.message)}<button class="pill secondary" data-creators-retry>重试</button></div>`;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-creators-retry]'))renderCreators();});

async function loadDiscovery(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3000);try{const response=await fetch('/api/discovery',{signal:controller.signal});if(response.ok){const data=await response.json();discoveryRanking=Array.isArray(data.items)?data.items:[];}}catch{}finally{clearTimeout(timer)}}
const clickedToday=new Set();
function recordClick(id){const key=Math.floor((Date.now()+8*3600000)/86400000)+':'+id;if(clickedToday.has(key))return;clickedToday.add(key);api('discovery',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})}).catch(()=>clickedToday.delete(key));}

setInterval(()=>{if(!document.hidden)loadDiscovery();},300000);
async function resumePendingDownload(){let pending;try{pending=JSON.parse(sessionStorage.getItem('ccbcm-pending-download')||'null');}catch{return;}if(!pending)return;if(Date.now()-pending.at>15*60000||!works.some(w=>w.id===pending.id)){try{sessionStorage.removeItem('ccbcm-pending-download');}catch{}return;}try{const a=await account();if(!a.user)return;await api('downloads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:pending.id})});sessionStorage.removeItem('ccbcm-pending-download');toast('已加入我的下载');if(pending.returnTo&&/^(discover|wallpapers|people\/[a-zA-Z0-9-]+|creator\/[a-zA-Z0-9-]+)$/.test(pending.returnTo)&&route!==pending.returnTo)location.hash=pending.returnTo;else if(route==='downloads')renderDownloads();}catch{toast('上次选择的壁纸暂未保存，请在作品中重新点击下载。');}}

